using System;using System.IO;using System.Globalization;using System.Linq;
namespace BeamScheduleFormatter {static class ReportFont {
 public static readonly string FontPath=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Fonts),File.Exists(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Fonts),"consola.ttf"))?"consola.ttf":"cour.ttf");public static string Family{get{return Path.GetFileName(FontPath).ToLowerInvariant()=="consola.ttf"?"Consolas":"Courier New";}}public static string PostScriptName{get{return Family=="Consolas"?"Consolas":"CourierNewPSMT";}}public static readonly byte[] Bytes=File.ReadAllBytes(FontPath);
 static int U16(int p){return (Bytes[p]<<8)|Bytes[p+1];}static int S16(int p){return (short)U16(p);}static int I32(int p){return (Bytes[p]<<24)|(Bytes[p+1]<<16)|(Bytes[p+2]<<8)|Bytes[p+3];}static int Table(string name){for(int i=0;i<U16(4);i++){int p=12+i*16;if(System.Text.Encoding.ASCII.GetString(Bytes,p,4)==name)return I32(p+8);}throw new Exception("Font table missing: "+name);}static double Scale{get{return 1000.0/U16(Table("head")+18);}}static string F(double n){return n.ToString("0.###",CultureInfo.InvariantCulture);}
 public static double Width{get{return U16(Table("hmtx"))*Scale;}}public static string Widths{get{return string.Join(" ",Enumerable.Repeat(F(Width),256));}}public static string Descriptor(int fileId){int head=Table("head"),hhea=Table("hhea");return "<< /Type /FontDescriptor /FontName /"+PostScriptName+" /Flags 33 /FontBBox ["+string.Join(" ",new[]{36,38,40,42}.Select(p=>F(S16(head+p)*Scale)))+"] /ItalicAngle 0 /Ascent "+F(S16(hhea+4)*Scale)+" /Descent "+F(S16(hhea+6)*Scale)+" /CapHeight 700 /StemV 80 /FontFile2 "+fileId+" 0 R >>";}
}}
